// FactAgentPerformance — generated by src/powerbi/build_assets.py from FactAgentPerformance.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "FactAgentPerformance.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"performance_id", type text},
        {"agent_id", type text},
        {"performance_date", type date},
        {"tickets_assigned", Int64.Type},
        {"tickets_resolved", Int64.Type},
        {"average_response_time", type number},
        {"average_resolution_time", type number},
        {"customer_satisfaction_score", type number},
        {"sla_compliance_rate", type number},
        {"workload_hours", type number},
        {"department_id", type text}
    }, "en-US")
in
    Typed
